181	bool MergeTreeReaderStream::hasAtMostNDistinctMarks(size_t max_transitions) const
182	{
183	    auto marks = marks_loader->loadMarks();
184	    size_t num_transitions = 0;
185	    MarkInCompressedFile last_mark{std::numeric_limits<size_t>::max(), std::numeric_limits<size_t>::max()};
186	    for (size_t i = 0; i < marks_count; ++i)
187	    {
188	        auto mark = marks->getMark(i, 0);
189	        if (mark != last_mark)
190	        {
191	            last_mark = mark;
192	            if (++num_transitions > max_transitions)
193	                return false;
194	        }
195	    }
196	    return true;
197	}
